import{_ as n,o as s,c as e,ai as r}from"./chunks/framework.Ai2o9gNv.js";const h=JSON.parse('{"title":"13-数组类型（1）","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/13-数组类型（1）/13-数组类型（1）.md","filePath":"仓颉入门到实战/13-数组类型（1）/13-数组类型（1）.md","lastUpdated":1734741109000,"__rawMarkdown":"# 13-数组类型（1）\\n\\n## 介绍\\n\\n数组类型使用Array来表示\\n\\n我们可以使用 Array 类型来构造单一元素类型，有序序列的数据。比如可以定义 字符串数组、数字数组、布尔数组。\\n\\n使用数组会更加方便我们管理一组相似的数据\\n\\n**Array 是一种长度不变的 Collection 类型， Array 没有提供添加和删除元素的成员函数**\\n\\n## 数组创建方式一 字面量方式\\n\\n该方式写法最简洁，比较常用\\n\\n```\\n    //  方式一 字面量方式\\n    let arr1 = [1, 2, 3, 4] // 数字数组\\n    let arr2 = [\'a\', \'b\', \'c\'] // 字符串数组\\n    // let arr3=[\'a\',100]// 不能存放不同类型的数据\\n```\\n\\n\\n\\n## 数组创建方式二 指定类型\\n\\n创建数组的时候还可以主动的指定类型\\n\\n```\\n    // 方式二 指定类型\\n    let arr3: Array<Int64> = [1, 2, 3]\\n```\\n\\n\\n\\n## 数组创建方式三 指定长度和内容\\n\\n这个方式比较适合我们创建指定长度和内容的数组\\n\\n```\\n    // 方式三 指定长度\\n    let arr4 = Array<Int64>() // 空数组\\n    let arr5 = Array<Int64>(5, {i => 100}) // 创建了5个100， i表示数组的每一个位置 从0开始，这里用不到，只是防止语法出错\\n    let arr6 = Array<Int64>(5, {i => i + 1}) // 5个元素，分别是 1、2、3、4、5\\n```\\n\\n## 访问数组\\n\\n我们可以访问数组的长度和数组中的每一个元素\\n\\n### 访问长度\\n\\nsize 是每一个数组都会拥有的属性，表示数组内元素的个数\\n\\n```\\n    let arr7 = [1, 2, 3, 4]\\n    print(arr7.size) // 4 \\n```\\n\\n### 访问单个元素\\n\\n我们想要访问元素是通过元素在数组中的位置来访问的。需要注意的是，开始的序号是从0开始。\\n\\n```\\n    // 访问元素\\n    let arr7 = [1, 2, 3, 4]\\n    print(arr7[0]) // 1 \\n    print(arr7[3]) // 4 \\n    print(arr7[20]) // 超出范围 便会报错 \\"array index 20 is past the end of array (which contains 4 elements)\\"\\n```\\n\\n### 访问一段范围内的元素\\n\\n我们可以通过特定语法，快速活动原数组中的一段范围内的元素\\n\\n```\\n    // 获取数组内的一段范围\\n    let arr8 = [\'a\', \'b\', \'c\', \'d\', \'e\']\\n    // let arr9 = arr8[0..3] // a b c  不包含 顺序为 3的元素\\n    let arr10 = arr8[..3] // a b c \\n    let arr11 = arr8[3..] // d e  \\n```\\n\\n## 修改数组\\n\\n这里的修改指的是修改数组的元素\\n\\n```\\n    // 修改元素\\n    let arr8 = [1, 2, 3, 4]\\n    arr8[1] = 100\\n    print(arr8[1]) // 100   \\n```\\n\\n"}'),p={name:"仓颉入门到实战/13-数组类型（1）/13-数组类型（1）.md"};function l(i,a,t,c,d,o){return s(),e("div",null,[...a[0]||(a[0]=[r("",29)])])}const u=n(p,[["render",l]]);export{h as __pageData,u as default};
